<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\ThemeAsset\Application\Usecase\Disable;

use Psr\EventDispatcher\EventDispatcherInterface;
use Throwable;
use Civi\Lughauth\Shared\Security\Allow;
use Civi\Lughauth\Shared\Exception\UnauthorizedException;
use Civi\Lughauth\Shared\Exception\NotFoundException;
use Civi\Lughauth\Features\Document\ThemeAsset\Domain\ThemeAssetRef;
use Civi\Lughauth\Features\Document\ThemeAsset\Application\Service\Visibility\ThemeAssetVisibilityService;
use Civi\Lughauth\Features\Document\ThemeAsset\Domain\Gateway\ThemeAssetWriteGateway;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class ThemeAssetDisableUsecase
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly EventDispatcherInterface $dispatcher,
        private readonly ThemeAssetVisibilityService $visibility,
        private readonly ThemeAssetWriteGateway $writer,
    ) {
    }

    public function allowDisable(?ThemeAssetRef $ref = null): Allow
    {
        $this->logDebug("Check allow of Disable usecase for Theme asset");
        $span = $this->startSpan("Check allow of Disable usecase for Theme asset");
        try {
            $result = $this->dispatcher->dispatch(new ThemeAssetDisableAllowDecision(Allow::allowed('disable', 'Allowed to Theme asset by default')));
            return $result->getAllow();
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function disable(string $uid): ThemeAssetDisableResult
    {
        $this->logDebug("Run Disable usecase for Theme asset");
        $span = $this->startSpan("Run Disable usecase for Theme asset");
        try {
            $ref = new ThemeAssetRef($uid);
            $allow = $this->allowDisable($ref);
            if (!$allow->allowed) {
                throw new UnauthorizedException($allow->reason ?? 'Not allowed to Disable Theme asset');
            }
            if (!$original = $this->visibility->retrieveVisibleForUpdate($ref)) {
                throw new NotFoundException($uid);
            }
            $this->dispatcher->dispatch(new ThemeAssetDisableCheck($original));
            $modified = $original->disable();
            $result = $this->writer->update($original, $modified);
            $output = $this->visibility->copyWithHidden($this->visibility->prepareVisibleData($result));
            return new ThemeAssetDisableResult($output);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
